public sealed class ValidateModelFilter : IAsyncActionFilter
{
    public async Task OnActionExecutionAsync(
        ActionExecutingContext context, ActionExecutionDelegate next)
    {
        if (!context.ModelState.IsValid)
        {
            context.Result = new ValidationProblemDetailsResult(context.ModelState);
            return; // action never runs
        }
        await next();
    }
}

// Register globally
builder.Services.AddControllers(options =>
    options.Filters.Add<ValidateModelFilter>());

public sealed class IdempotencyFilter(
    IIdempotencyStore store,
    ILogger<IdempotencyFilter> logger) : IAsyncActionFilter
{
    public async Task OnActionExecutionAsync(
        ActionExecutingContext context, ActionExecutionDelegate next)
    {
        var key = context.HttpContext.Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (key is null) { await next(); return; }

        if (await store.TryGetCachedResponseAsync(key) is { } cached)
        {
            context.Result = cached;
            return;
        }

        var executed = await next();
        if (executed.Result is ObjectResult ok)
            await store.SaveAsync(key, ok);
    }
}

[TypeFilter(typeof(IdempotencyFilter))]
[HttpPost("orders")]
public IActionResult CreateOrder(CreateOrderRequest req) => Ok(new { id = 1 });

public sealed class TimingFilter : IAsyncActionFilter, IOrderedFilter
{
    public int Order => int.MaxValue - 10; // late on way in, early on way out

    public async Task OnActionExecutionAsync(
        ActionExecutingContext context, ActionExecutionDelegate next)
    {
        var sw = Stopwatch.StartNew();
        var executed = await next();
        sw.Stop();
        context.HttpContext.Response.Headers["X-Action-Ms"] = sw.ElapsedMilliseconds.ToString();
    }
}

public sealed class DomainExceptionFilter : IExceptionFilter
{
    public void OnException(ExceptionContext context)
    {
        if (context.Exception is DomainValidationException ex)
        {
            context.Result = new ObjectResult(new ValidationProblemDetails(ex.Errors))
            {
                StatusCode = StatusCodes.Status400BadRequest
            };
            context.ExceptionHandled = true;
        }
    }
}
// Exception filters only catch exceptions from actions/filters after them — not middleware
